'use client';

import React, { useState, useEffect } from 'react';
import { useStore } from '../store/useStore';
import { Search, Bell, ShoppingCart, ArrowLeft, X, HelpCircle, Globe, User } from 'lucide-react';
import Link from 'next/link';
import { usePathname, useRouter } from 'next/navigation';

export default function MobileHeader() {
  const {
    cart,
    mobileTab,
    setMobileTab,
    searchQuery,
    setSearchQuery,
    setSelectedCategory,
    categories,
    notifications,
    unreadCount,
    markNotificationAsRead,
    markAllNotificationsAsRead,
    language,
    setLanguage,
    isLoggedIn,
    username,
    syncAuthFromStorage
  } = useStore();

  const pathname = usePathname();
  const router = useRouter();

  const [showSearchOverlay, setShowSearchOverlay] = useState(false);
  const [localSearch, setLocalSearch] = useState(searchQuery);
  const [notificationsOpen, setNotificationsOpen] = useState(false);

  const cartCount = cart.reduce((acc, item) => acc + item.quantity, 0);

  useEffect(() => {
    setLocalSearch(searchQuery);
  }, [searchQuery]);

  const handleLogoClick = () => {
    setMobileTab('home');
    if (pathname !== '/') {
      router.push('/');
    }
  };

  const handleCartClick = () => {
    setMobileTab('cart');
    if (pathname !== '/') {
      router.push('/');
    }
  };

  const handleSearchSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setSearchQuery(localSearch);
    setShowSearchOverlay(false);
    setMobileTab('home');
    if (pathname !== '/') {
      router.push('/');
    }
  };

  const handleSuggestionClick = (text: string) => {
    setLocalSearch(text);
    setSearchQuery(text);
    setShowSearchOverlay(false);
    setMobileTab('home');
    if (pathname !== '/') {
      router.push('/');
    }
  };

  const handleNotificationClick = (id: string) => {
    markNotificationAsRead(id);
  };

  const toggleLang = () => {
    const nextLang = language === 'en' ? 'bn' : 'en';
    setLanguage(nextLang);
  };

  return (
    <>
      <header className="sticky top-0 z-40 bg-white border-b border-neutral-light/70 shadow-sm h-14 flex items-center justify-between px-3 md:hidden">
        {/* Brand Logo */}
        <div 
          onClick={handleLogoClick}
          className="flex items-center gap-1.5 cursor-pointer select-none active:scale-95 transition-transform shrink-0"
        >
          <div className="w-8 h-8 rounded-lg bg-primary flex items-center justify-center font-black text-neutral-dark text-lg shadow-sm">
            Z
          </div>
          <span className="font-extrabold text-base text-neutral-dark tracking-tight hidden xs:inline">
            Zibon<span className="text-primary-accent">baba</span>
          </span>
        </div>

        {/* Search Box - triggers overlay */}
        <div 
          onClick={() => setShowSearchOverlay(true)}
          className="flex-grow mx-2 bg-neutral-light border border-neutral-light/80 rounded-lg flex items-center h-8 px-2.5 text-neutral-muted text-xs font-semibold cursor-pointer active:bg-neutral-muted/10 transition-colors"
        >
          <Search className="w-3.5 h-3.5 mr-1.5 shrink-0 text-neutral-muted" />
          <span className="line-clamp-1 text-[11px]">
            {searchQuery || (language === 'en' ? 'Search catalog, SKUs...' : 'পণ্য ও এসকেইউ খুঁজুন...')}
          </span>
        </div>

        {/* Action Icons */}
        <div className="flex items-center gap-1 shrink-0">
          {/* Language Switcher */}
          <button
            onClick={toggleLang}
            className="px-2 py-1 bg-neutral-light hover:bg-neutral-muted/20 text-[10px] font-black text-neutral-dark rounded-md border border-neutral-light/80 transition-all flex items-center gap-1 active:scale-90"
            title="Toggle English / বাংলা"
          >
            <Globe className="w-3 h-3 text-primary-accent" />
            <span>{language === 'en' ? 'বাং' : 'EN'}</span>
          </button>

          {/* Notifications */}
          <div className="relative">
            <button
              onClick={() => setNotificationsOpen(!notificationsOpen)}
              className="p-1.5 hover:bg-neutral-light rounded-full transition-colors relative active:scale-90"
              aria-label="Notifications"
            >
              <Bell className="w-4.5 h-4.5 text-neutral-dark" />
              {unreadCount > 0 && (
                <span className="absolute top-0.5 right-0.5 bg-error text-white text-[8px] font-bold w-4 h-4 rounded-full flex items-center justify-center border border-white">
                  {unreadCount}
                </span>
              )}
            </button>

            {/* Notification Drawer Popover */}
            {notificationsOpen && (
              <div className="absolute right-0 mt-2 w-72 bg-white border border-neutral-light shadow-modal rounded-xl py-2.5 z-50 animate-slide-up">
                <div className="flex items-center justify-between px-4 pb-2 border-b border-neutral-light/70 mb-1.5">
                  <span className="text-xs font-bold text-neutral-dark">Notifications</span>
                  <button 
                    onClick={() => markAllNotificationsAsRead()}
                    className="text-[9px] text-primary-dark font-bold hover:underline"
                  >
                    Mark all read
                  </button>
                </div>
                <div className="max-h-60 overflow-y-auto space-y-1">
                  {notifications.length === 0 ? (
                    <p className="text-center text-[10px] text-neutral-muted py-6">No new updates</p>
                  ) : (
                    notifications.map(n => (
                      <div 
                        key={n.id} 
                        onClick={() => handleNotificationClick(n.id)}
                        className={`px-4 py-2 hover:bg-neutral-light cursor-pointer transition-colors ${!n.isRead ? 'bg-primary/5' : ''}`}
                      >
                        <div className="flex items-center justify-between">
                          <span className="text-[10px] font-bold text-neutral-dark truncate max-w-[150px]">{n.title}</span>
                          <span className="text-[8px] text-neutral-muted">{new Date(n.createdAt).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</span>
                        </div>
                        <p className="text-[9px] text-neutral-body mt-0.5 leading-snug line-clamp-2">{n.body}</p>
                      </div>
                    ))
                  )}
                </div>
                <div className="border-t border-neutral-light mt-1.5 pt-2 text-center">
                  <Link
                    href="/notifications"
                    onClick={() => setNotificationsOpen(false)}
                    className="text-[9px] text-primary-dark font-extrabold block hover:underline"
                  >
                    Open Notification Center →
                  </Link>
                </div>
              </div>
            )}
          </div>

          {/* Cart Icon */}
          <button
            onClick={handleCartClick}
            className={`p-1.5 rounded-full transition-colors relative active:scale-90 ${mobileTab === 'cart' ? 'bg-primary/20 text-primary-dark font-extrabold' : 'text-neutral-dark'}`}
            aria-label="Cart"
          >
            <ShoppingCart className="w-4.5 h-4.5" />
            {cartCount > 0 && (
              <span className="absolute top-0.5 right-0.5 bg-primary-accent text-neutral-dark text-[8px] font-extrabold w-4 h-4 rounded-full flex items-center justify-center border border-white animate-pulse">
                {cartCount}
              </span>
            )}
          </button>

          {/* Account Profile / Sign In Link */}
          {isLoggedIn ? (
            <Link
              href="/dashboard"
              className="w-7 h-7 rounded-lg bg-amber-500 flex items-center justify-center text-xs font-black text-slate-950 uppercase shadow-xs active:scale-90 transition-transform ml-0.5"
              title="My Account"
            >
              {(username || 'U').charAt(0)}
            </Link>
          ) : (
            <Link
              href="/login"
              className="p-1.5 hover:bg-neutral-light rounded-full text-neutral-dark active:scale-90 transition-transform ml-0.5"
              title="Sign In"
            >
              <User className="w-4.5 h-4.5" />
            </Link>
          )}
        </div>
      </header>

      {/* FULL-SCREEN SEARCH OVERLAY */}
      {showSearchOverlay && (
        <div className="fixed inset-0 z-50 bg-white flex flex-col md:hidden animate-fade-in">
          {/* Search Header Input */}
          <div className="h-14 border-b border-neutral-light flex items-center px-4 gap-3">
            <button 
              onClick={() => setShowSearchOverlay(false)}
              className="p-1 hover:bg-neutral-light rounded-full transition-colors"
            >
              <ArrowLeft className="w-5 h-5 text-neutral-dark" />
            </button>
            <form onSubmit={handleSearchSubmit} className="flex-grow flex items-center bg-neutral-light rounded-md border border-neutral-light focus-within:border-primary-accent px-2">
              <input
                type="text"
                autoFocus
                placeholder="Search products, brands, categories..."
                value={localSearch}
                onChange={(e) => setLocalSearch(e.target.value)}
                className="w-full bg-transparent text-xs py-2 px-1 outline-none text-neutral-dark placeholder:text-neutral-muted font-medium"
              />
              {localSearch && (
                <button 
                  type="button" 
                  onClick={() => setLocalSearch('')}
                  className="p-0.5 hover:bg-neutral-muted/20 rounded-full"
                >
                  <X className="w-3.5 h-3.5 text-neutral-body" />
                </button>
              )}
            </form>
            <button 
              onClick={handleSearchSubmit}
              className="text-xs font-bold text-neutral-dark bg-primary hover:bg-primary-dark px-3 py-2 rounded-md transition-colors"
            >
              Search
            </button>
          </div>

          {/* Suggestions Content */}
          <div className="flex-1 overflow-y-auto px-4 py-4 space-y-5">
            {/* Popular Searches */}
            <div>
              <h3 className="text-[10px] font-bold text-neutral-muted uppercase tracking-wider mb-2.5">Popular Searches</h3>
              <div className="flex flex-wrap gap-2">
                {['Wireless Headphones', 'Smart Mug', 'Sneakers', 'Laptop Stand', 'Leather Journal', 'Condenser Mic'].map((kw) => (
                  <button
                    key={kw}
                    onClick={() => handleSuggestionClick(kw)}
                    className="text-xs bg-neutral-light hover:bg-primary/20 text-neutral-dark font-semibold px-3.5 py-1.5 rounded-full border border-neutral-light transition-all active:scale-95"
                  >
                    {kw}
                  </button>
                ))}
              </div>
            </div>

            {/* Quick Categories Filter */}
            <div>
              <h3 className="text-[10px] font-bold text-neutral-muted uppercase tracking-wider mb-2.5">Search by Category</h3>
              <div className="space-y-1">
                {categories.map((cat) => (
                  <button
                    key={cat}
                    onClick={() => {
                      setSelectedCategory(cat);
                      setShowSearchOverlay(false);
                      setMobileTab('home');
                      if (pathname !== '/') {
                        router.push('/');
                      }
                    }}
                    className="w-full flex items-center justify-between text-left py-2.5 border-b border-neutral-light text-xs font-semibold text-neutral-dark active:text-primary-dark"
                  >
                    <span>{cat}</span>
                    <span className="text-[10px] text-neutral-muted">Browse →</span>
                  </button>
                ))}
              </div>
            </div>

            {/* Helper tips */}
            <div className="bg-neutral-light p-4 rounded-lg flex gap-3 items-start border border-neutral-light/50">
              <HelpCircle className="w-4 h-4 text-primary-accent shrink-0 mt-0.5" />
              <div>
                <p className="text-[10px] font-bold text-neutral-dark">Search Smart Tip</p>
                <p className="text-[9px] text-neutral-body mt-0.5 leading-relaxed">
                  Type specific SKU codes (e.g. `HP-PRO-WHT` or `RUN-CNV-RED`) to find specific warehouse items immediately.
                </p>
              </div>
            </div>
          </div>
        </div>
      )}
    </>
  );
}

'use client';

import React, { useState, useEffect } from 'react';
import { useStore, Product } from '../store/useStore';
import {
  Percent,
  Star,
  ShoppingBag,
  Flame,
  Clock,
  Heart,
  ChevronRight,
  Store,
  SlidersHorizontal,
  Package,
  ShoppingCart,
  ShieldCheck,
  ArrowRight,
  Truck,
  Users,
  CheckCircle,
  Gift,
  Tag,
  ThumbsUp,
  Sparkles
} from 'lucide-react';
import Link from 'next/link';
import { translations } from '../utils/translations';

export default function MobileHomepage() {
  const {
    products,
    categories,
    setSelectedCategory,
    setMobileTab,
    wishlist,
    toggleWishlist,
    addToCart,
    language
  } = useStore();

  const t = translations[language];

  // Hero Slider State
  const [activeSlide, setActiveSlide] = useState(0);
  const slides = [
    {
      id: 1,
      image: 'https://images.unsplash.com/photo-1534528741775-53994a69daeb?w=800&auto=format&fit=crop&q=60',
      title: 'Just For You',
      desc: 'Get flat 30% off on premium catalog',
      linkText: 'Shop Apparel',
      cat: 'Apparel'
    },
    {
      id: 2,
      image: 'https://images.unsplash.com/photo-1556228720-195a672e8a03?w=800&auto=format&fit=crop&q=60',
      title: 'Radiant Skin Special',
      desc: 'Up to 20% off on verified skincare',
      linkText: 'Explore Beauty',
      cat: 'Home & Kitchen'
    },
    {
      id: 3,
      image: 'https://images.unsplash.com/photo-1509631179647-0177331693ae?w=800&auto=format&fit=crop&q=60',
      title: 'Trending Outfits',
      desc: 'Exclusive new catalog designs active now',
      linkText: 'Discover Now',
      cat: 'Apparel'
    }
  ];

  const [timeLeft, setTimeLeft] = useState({ hrs: 2, min: 14, sec: 45 });
  const [recentlyViewed, setRecentlyViewed] = useState<Product[]>([]);
  const [activeHomeTab, setActiveHomeTab] = useState<'trending' | 'new-arrivals'>('trending');

  useEffect(() => {
    const slideInterval = setInterval(() => {
      setActiveSlide(prev => (prev + 1) % slides.length);
    }, 4500);

    const timer = setInterval(() => {
      setTimeLeft(prev => {
        if (prev.sec > 0) return { ...prev, sec: prev.sec - 1 };
        if (prev.min > 0) return { ...prev, min: prev.min - 1, sec: 59 };
        if (prev.hrs > 0) return { hrs: prev.hrs - 1, min: 59, sec: 59 };
        clearInterval(timer);
        return prev;
      });
    }, 1000);

    const savedRecentIds = localStorage.getItem('zibonbaba-recent');
    if (savedRecentIds) {
      try {
        const ids: string[] = JSON.parse(savedRecentIds);
        const filtered = ids
          .map(id => products.find(p => p.id === id))
          .filter((p): p is Product => !!p);
        setRecentlyViewed(filtered.slice(0, 5));
      } catch (err) {
        console.error('Failed to parse recently viewed', err);
      }
    } else {
      setRecentlyViewed(products.slice(0, 2));
    }

    return () => {
      clearInterval(slideInterval);
      clearInterval(timer);
    };
  }, [products]);

  const formatNum = (num: number) => String(num).padStart(2, '0');

  return (
    <div className="flex-1 bg-slate-50 text-slate-800 pb-24 overflow-x-hidden animate-slide-up">

      {/* 1. HERO BANNER SLIDER */}
      <section className="relative w-full h-[220px] bg-slate-900 overflow-hidden">
        {slides.map((slide, idx) => {
          const displayTitle = language === 'en' ? slide.title :
            slide.title === 'Just For You' ? 'শুধু আপনার জন্য' :
            slide.title === 'Radiant Skin Special' ? 'উজ্জ্বল ত্বকের বিশেষ অফার' :
            slide.title === 'Trending Outfits' ? 'ট্রেন্ডিং পোশাক কালেকশন' : slide.title;

          const displayDesc = language === 'en' ? slide.desc :
            slide.desc === 'Get flat 30% off on premium catalog' ? 'প্রিমিয়াম ক্যাটালগে ফ্ল্যাট ৩০% ছাড়' :
            slide.desc === 'Up to 20% off on verified skincare' ? 'যাচাইকৃত স্কিনকেয়ারে ২০% পর্যন্ত ছাড়' :
            slide.desc === 'Exclusive new catalog designs active now' ? 'এক্সক্লুসিভ নতুন ক্যাটালগ ডিজাইন সক্রিয়' : slide.desc;

          const displayLinkText = language === 'en' ? slide.linkText :
            slide.linkText === 'Shop Apparel' ? 'পোশাক কিনুন' :
            slide.linkText === 'Explore Beauty' ? 'সৌন্দর্য পণ্য দেখুন' :
            slide.linkText === 'Discover Now' ? 'আবিষ্কার করুন' : slide.linkText;

          return (
            <div
              key={slide.id}
              className={`absolute inset-0 transition-opacity duration-1000 ease-in-out ${idx === activeSlide ? 'opacity-100' : 'opacity-0 pointer-events-none'}`}
            >
              <div className="absolute inset-0 bg-gradient-to-r from-black/70 via-black/40 to-transparent z-10"></div>
              <img src={slide.image} alt={displayTitle} className="w-full h-full object-cover" />

              <div className="absolute inset-x-5 inset-y-0 z-20 flex flex-col justify-center text-white">
                <span className="bg-amber-500 text-slate-950 text-[9px] font-black uppercase px-2.5 py-1 rounded-full w-fit mb-2 shadow-sm tracking-wider">
                  {language === 'en' ? 'Special Campaign' : 'বিশেষ ক্যাম্পেইন'}
                </span>
                <h2 className="text-xl font-black leading-tight drop-shadow-md">{displayTitle}</h2>
                <p className="text-[11px] text-slate-200 mt-1 line-clamp-1 leading-tight">{displayDesc}</p>
                <button
                  onClick={() => {
                    setSelectedCategory(slide.cat);
                    setMobileTab('categories');
                  }}
                  className="bg-[#FFC107] hover:bg-amber-600 text-slate-950 text-[10px] font-black px-4 py-2 rounded-xl w-fit mt-4 active:scale-95 transition-transform uppercase tracking-wider"
                >
                  {displayLinkText}
                </button>
              </div>
            </div>
          );
        })}
        <div className="absolute bottom-3 right-5 z-20 flex gap-1.5">
          {slides.map((_, idx) => (
            <button
              key={idx}
              onClick={() => setActiveSlide(idx)}
              className={`w-1.5 h-1.5 rounded-full transition-all ${idx === activeSlide ? 'bg-amber-500 w-3.5' : 'bg-white/50'}`}
            ></button>
          ))}
        </div>
      </section>

      {/* 2. POPULAR CATEGORIES */}
      <section className="bg-white px-4 py-6 border-b border-slate-100 shadow-sm">
        <div className="flex justify-between items-center mb-4">
          <h3 className="text-xs font-black text-slate-800 uppercase tracking-wider">Popular Categories</h3>
          <button
            onClick={() => { setSelectedCategory('All'); setMobileTab('categories'); }}
            className="text-[10px] text-amber-500 font-extrabold flex items-center"
          >
            <span>View All</span> <ChevronRight className="w-3 h-3" />
          </button>
        </div>
        <div className="flex gap-4 overflow-x-auto pb-1.5 scrollbar-none -mx-4 px-4">
          {[
            { name: language === 'en' ? 'Electronics' : 'ইলেকট্রনিক্স', cat: 'Electronics', img: 'https://images.unsplash.com/photo-1588872657578-7efd1f1555ed?w=150&auto=format&fit=crop&q=80' },
            { name: language === 'en' ? 'Fashion' : 'ফ্যাশন', cat: 'Apparel', img: 'https://images.unsplash.com/photo-1595777457583-95e059d581b8?w=150&auto=format&fit=crop&q=80' },
            { name: language === 'en' ? 'Grocery' : 'মুদিখানা', cat: 'Home & Kitchen', img: 'https://images.unsplash.com/photo-1542838132-92c53300491e?w=150&auto=format&fit=crop&q=80' },
            { name: language === 'en' ? 'Beauty' : 'রূপচর্চা', cat: 'Home & Kitchen', img: 'https://images.unsplash.com/photo-1522335789203-aabd1fc54bc9?w=150&auto=format&fit=crop&q=80' },
            { name: language === 'en' ? 'Home' : 'গৃহসজ্জা', cat: 'Home & Kitchen', img: 'https://images.unsplash.com/photo-1513694203232-719a280e022f?w=150&auto=format&fit=crop&q=80' },
          ].map((item, idx) => (
            <div
              key={idx}
              onClick={() => {
                setSelectedCategory(item.cat);
                setMobileTab('categories');
              }}
              className="flex flex-col items-center cursor-pointer select-none shrink-0"
            >
              <div className="w-14 h-14 rounded-full overflow-hidden shadow-sm border border-slate-100 relative bg-slate-50 flex items-center justify-center">
                <img src={item.img} alt={item.name} className="w-full h-full object-cover" />
              </div>
              <span className="text-[10px] font-extrabold text-slate-650 mt-2 leading-tight">
                {item.name}
              </span>
            </div>
          ))}
        </div>
      </section>

      {/* 3. FLASH DEALS */}
      <section className="bg-white mt-3.5 border-t border-b border-slate-100 py-5 px-4 shadow-sm">
        <div className="flex items-center justify-between mb-4">
          <div className="flex items-center gap-1.5">
            <div className="bg-red-500 text-white p-1 rounded-lg">
              <Flame className="w-4 h-4 fill-current animate-pulse" />
            </div>
            <h2 className="text-xs font-black text-slate-800 uppercase tracking-wider">{t.flashSale}</h2>
            <div className="flex items-center gap-1 ml-2">
              <span className="bg-red-500 text-white font-black text-[10px] px-2 py-0.5 rounded-lg shadow-sm">{formatNum(timeLeft.hrs)}</span>
              <span className="text-[10px] font-bold text-red-500">:</span>
              <span className="bg-red-500 text-white font-black text-[10px] px-2 py-0.5 rounded-lg shadow-sm">{formatNum(timeLeft.min)}</span>
              <span className="text-[10px] font-bold text-red-500">:</span>
              <span className="bg-red-500 text-white font-black text-[10px] px-2 py-0.5 rounded-lg shadow-sm">{formatNum(timeLeft.sec)}</span>
            </div>
          </div>
        </div>

        <div className="flex gap-4 overflow-x-auto pb-2 -mx-4 px-4 scrollbar-none snap-x">
          {products.slice(0, 3).map((p) => {
            const isWished = wishlist.includes(p.id);
            return (
              <div key={p.id} className="w-[145px] shrink-0 bg-slate-50 border border-slate-200/60 rounded-2xl p-3 snap-start shadow-sm flex flex-col justify-between">
                <div className="relative">
                  <Link href={`/product/${p.id}`} className="block relative aspect-square bg-white rounded-xl overflow-hidden mb-2 border border-slate-100">
                    <img src={p.image} alt={p.name} className="object-cover w-full h-full" />
                  </Link>
                  <span className="absolute top-1.5 left-1.5 bg-red-500 text-white font-black text-[8px] px-2 py-0.5 rounded-full shadow-sm">
                    -20% OFF
                  </span>
                  <button
                    onClick={() => toggleWishlist(p.id)}
                    className="absolute top-1.5 right-1.5 p-1.5 bg-white/95 rounded-full shadow-sm text-slate-400 hover:text-red-500 border border-slate-100"
                  >
                    <Star className={`w-3 h-3 ${isWished ? 'text-amber-400 fill-current' : ''}`} />
                  </button>
                </div>
                <div>
                  <h4 className="text-[11px] font-black text-slate-800 line-clamp-1 leading-tight">{p.name}</h4>
                  <p className="text-[9px] text-slate-400 font-bold mt-0.5">{p.vendor}</p>

                  <div className="flex items-baseline gap-1.5 mt-1.5">
                    <span className="text-sm font-black text-slate-800">৳{(p.price * 80 * 0.8).toFixed(0)}</span>
